def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    """
    Process a list of bank operations with undo support.

    Returns:
        (balances, rejected)
        balances: dict mapping account name -> final balance (only existing accounts)
        rejected: list of operation indices that failed
    """
    accounts: dict[str, int] = {}
    frozen: dict[str, bool] = {}

    # Stack of successful operations to allow undo.
    # Each element is a tuple (op_type, data) where data depends on op_type.
    # op_type one of: "open", "deposit", "withdraw", "transfer", "freeze", "unfreeze"
    stack: list[tuple[str, tuple]] = []

    rejected: list[int] = []

    def is_valid_amount(tok: str) -> bool:
        return tok.isdigit()  # non‑empty, all digits

    for idx, line in enumerate(ops):
        parts = line.split(' ')
        verb = parts[0] if parts else ''
        success = False

        # Helper to record failure
        def fail():
            nonlocal success
            rejected.append(idx)
            success = False

        # ----- operation handling -----
        if verb == 'open' and len(parts) == 3:
            _, name, amt = parts
            if name in accounts or not is_valid_amount(amt):
                fail()
            else:
                amount = int(amt)
                # N >= 0 always true for digit strings
                accounts[name] = amount
                frozen[name] = False
                stack.append(('open', (name,)))
                success = True

        elif verb == 'deposit' and len(parts) == 3:
            _, name, amt = parts
            if not is_valid_amount(amt):
                fail()
            else:
                amount = int(amt)
                if amount <= 0 or name not in accounts:
                    fail()
                else:
                    accounts[name] += amount
                    stack.append(('deposit', (name, amount)))
                    success = True

        elif verb == 'withdraw' and len(parts) == 3:
            _, name, amt = parts
            if not is_valid_amount(amt):
                fail()
            else:
                amount = int(amt)
                if amount <= 0 or name not in accounts or frozen.get(name, False) or accounts[name] < amount:
                    fail()
                else:
                    accounts[name] -= amount
                    stack.append(('withdraw', (name, amount)))
                    success = True

        elif verb == 'transfer' and len(parts) == 4:
            _, src, dst, amt = parts
            if not is_valid_amount(amt):
                fail()
            else:
                amount = int(amt)
                cond = (
                    amount > 0 and
                    src != dst and
                    src in accounts and
                    dst in accounts and
                    not frozen.get(src, False) and
                    accounts[src] >= amount
                )
                if not cond:
                    fail()
                else:
                    accounts[src] -= amount
                    accounts[dst] += amount
                    stack.append(('transfer', (src, dst, amount)))
                    success = True

        elif verb == 'freeze' and len(parts) == 2:
            _, name = parts
            if name not in accounts or frozen.get(name, False):
                fail()
            else:
                prev = frozen[name]
                frozen[name] = True
                stack.append(('freeze', (name, prev)))
                success = True

        elif verb == 'unfreeze' and len(parts) == 2:
            _, name = parts
            if name not in accounts or not frozen.get(name, False):
                fail()
            else:
                prev = frozen[name]
                frozen[name] = False
                stack.append(('unfreeze', (name, prev)))
                success = True

        elif verb == 'undo' and len(parts) == 1:
            if not stack:
                fail()
            else:
                op_type, data = stack.pop()
                # Revert the operation
                if op_type == 'open':
                    (name,) = data
                    # delete account
                    accounts.pop(name, None)
                    frozen.pop(name, None)
                elif op_type == 'deposit':
                    name, amount = data
                    accounts[name] = accounts.get(name, 0) - amount
                elif op_type == 'withdraw':
                    name, amount = data
                    accounts[name] = accounts.get(name, 0) + amount
                elif op_type == 'transfer':
                    src, dst, amount = data
                    accounts[src] = accounts.get(src, 0) + amount
                    accounts[dst] = accounts.get(dst, 0) - amount
                elif op_type in ('freeze', 'unfreeze'):
                    name, prev_state = data
                    frozen[name] = prev_state
                # undo itself cannot be undone, so we do not push anything
                success = True
        else:
            # unknown verb or wrong token count
            fail()

        # If operation failed, nothing was pushed onto the stack (already handled)
        # Ensure success flag is set appropriately (already done)
        if not success and verb != 'undo':
            # In cases where we fell through without calling fail()
            pass

    # Prepare final balances dict (only existing accounts)
    final_balances = {name: bal for name, bal in accounts.items()}
    return final_balances, rejected
